    const changedSource=await cleanClient.preparePlan({candidate:monsterInput(proofMob),sourceItemHints:['Proof Relic'],matchesReviewed:true}),writesBeforeChange=writes.length;pages.get('Proof Relic').revision++;pages.get('Proof Relic').text+='\nSomeone changed this source after Preview.';await assert.rejects(cleanClient.submitPlan({planId:changedSource.id,reviewDigest:changedSource.reviewDigest}),/changed after review/);assert.equal(writes.length,writesBeforeChange,'Changed recovery evidence blocks all writes before publication');
    const retryMob='Retry Source Guardian',retryItem='Retry Source Relic',retryRecord=sourcePage(retryItem,retryMob);backlinks.set(retryMob,{query:{backlinks:[retryRecord]}});const retryPlan=await cleanClient.preparePlan({candidate:{...monsterInput(retryMob),fields:{...monsterInput(retryMob).fields,knownLoot:{value:[retryItem,'Existing Contract Relic'],confirmed:true}}},matchesReviewed:true});assert.deepEqual(retryPlan.blockers,[]);assert(retryPlan.pages.some(page=>page.title===retryItem),'A missing category is a normal reciprocal source patch');unknownTitle=retryItem;const lostRecovery=await cleanClient.submitPlan({planId:retryPlan.id,reviewDigest:retryPlan.reviewDigest});assert.equal(lostRecovery.status,'partial');assert.equal(lostRecovery.pages.find(page=>page.title===retryItem).status,'unknown');const recoveryRetryClient=new WikiClient({origin,allowLoopbackDevelopment:true,fetchImpl:fetchWithCookie,stateDir:path.join(stateDir,'clean-later-mob')});assert.equal((await recoveryRetryClient.submitPlan({planId:retryPlan.id,reviewDigest:retryPlan.reviewDigest})).status,'submitted');assert.equal(writes.filter(write=>write.title===retryItem).length,1,'A recovered source changed by this reviewed plan reconciles without repeating the edit');assert.equal(writes.filter(write=>write.title===retryMob).length,1,'Recovery retry does not recreate the mob');
